                  (Z_to_bv 64 allocb) (Z_to_bv 64 p) (Z_to_bv 64 (atd_size A)) (Z_to_bv 64 8) (Z_to_bv 64 P_A_ALLOCIMPL_DEALLOCATE) a5 a6 a7
