             F (Z_to_bv 64 P_A_ALLOCIMPL_DEALLOCATE) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp + -16, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
