Lemma atd_segA : forall A, atd_entry_ok A ->
  forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         (F : bvmap 5 word) fc (m : mem) (AT p allocb lo shi : Z) (junk : list byte),
    ro_cells bsegs m AT [C8 (wz allocb)] -> bv_unsigned sp <= AT -> AT + 8 <= shi -> AT mod 8 = 0 ->
    rw_cells bsegs m allocb [C8 (wz AVP_ALLOCIMPL); CB 8 junk] -> addressable m allocb 16 ->
    0 < allocb -> allocb mod 8 = 0 -> allocb + 16 <= aceil ->
    AXStatics2 m ->
    stk bsegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> aceil <= lo ->
    mem_inv bsegs m -> ACONST m -> stack0 m lo shi ->
    evt bsegs (atd_segA_post sp gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc A p allocb lo ra m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 AT) (Z_to_bv 64 p) (Z_to_bv 64 1) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 A) fc None m (seg_rom bsegs)).
