Lemma atd_segC : forall A, atd_entry_ok A ->
  forall (pcv rax sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (s0v rav : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo : Z),
    (pcv = Z_to_bv 64 (atd_ret A) \/ pcv = ret_pc (Z_to_bv 64 (atd_ret A))) ->
    rw_cells bsegs m (bv_unsigned sp + -16) [C8 s0v; C8 rav] ->
    stk bsegs m lo (bv_unsigned sp + -16) -> lo + 16 <= bv_unsigned sp -> aceil <= lo ->
    mem_inv bsegs m ->
    evt bsegs (fun ms' =>
        ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                 F (ret_pc rav) fc None m (seg_rom bsegs)
        /\ stk bsegs m lo (bv_unsigned sp))
      (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
