Definition dobj_tail_atd (T : Z) : Z :=
  if T =? P_A_DEALLOC_OBJ_CONFIG + 0x70 then P_B_ATD_CONFIG else if T =? P_A_DEALLOC_OBJ_SCHED + 0x70 then P_B_ATD_SCHED else P_B_ATD_SSVC.

Lemma dobj_tail_atd_ok : forall T size, dobj_tail_ok T size -> atd_entry_ok (dobj_tail_atd T) /\ atd_size (dobj_tail_atd T) = size.
Proof.
  intros T size [[-> ->]|[[-> ->]|[-> ->]]]; unfold dobj_tail_atd, atd_entry_ok, atd_size; cbn; split; auto.
Qed.

