(* [comment removed for export] *)
Lemma dobj_cfg_pre : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
       (F : bvmap 5 word) fc (m : mem) (AT p allocb lo shi : Z),
  ro_cells bsegs m AT [C8 (wz allocb)] -> bv_unsigned sp <= AT -> AT + 8 <= shi -> AT mod 8 = 0 ->
  ro_cells bsegs m p [C8 (wz AVP_CONFIG_SVC)] -> 0 < p -> p mod 8 = 0 -> p + 8 <= aceil -> accessible m p 8 ->
  0 <= allocb < 2^64 ->
  AXStatics2 m ->
  stk bsegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m -> ACONST m -> stack0 m lo shi ->
  evt bsegs (fun ms' => exists a1 a2 a3 m' junk,
      ms' = MS (mkR (Z_to_bv 64 (P_A_DEALLOC_OBJ_CONFIG + 0x70)) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (Z_to_bv 64 p) s1
                    (Z_to_bv 64 p) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc (Z_to_bv 64 (P_A_DEALLOC_OBJ_CONFIG + 0x70))) fc None m' (seg_rom bsegs)
      /\ munch [(bv_unsigned sp + -32, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
      /\ stk bsegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells bsegs m' (bv_unsigned sp + -32) (dobj_frame junk allocb s0 ra))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 AT) (Z_to_bv 64 p) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_DEALLOC_OBJ_CONFIG) fc None m (seg_rom bsegs)).
Proof.
  intros until shi. intros HAT SPA ATS AT8 HP P0 P8 PHI ACP ALR XS ST LO CEIL MI AC SK.
  eapply evt_cut.
  { eapply (dobj_segA P_A_DEALLOC_OBJ_CONFIG ltac:(left; reflexivity)) with (AT := AT) (p := p) (allocb := allocb) (lo := lo) (shi := shi); fast_eassumption. }
  intros ms' (a1v & a2v & a3v & m1 & junk & -> & MU & WM & MI1 & ST1 & FR1).
